// ─────────────────────────────────────────────
// M3-B: memory injection for explore prompt
// ─────────────────────────────────────────────

export interface FormatMemoryForPromptOptions {
  /** Override memory root (tests). */
  root?: string;
}

/** Load persistent brain entries and format as compact reference text for the explore prompt. */
export function formatMemoryForPrompt(opts?: FormatMemoryForPromptOptions): string {
  const { byCategory } = loadMemory({
    categories: MEMORY_INJECTION_CATEGORIES,
    root: opts?.root,
  });

  const lines: string[] = [];
  let totalChars = 0;
  let truncated = false;
  let totalEntries = 0;

  for (const cat of MEMORY_INJECTION_CATEGORIES) {
    const catEntries = byCategory[cat];
    if (!catEntries?.length) continue;
    totalEntries += catEntries.length;

    const header = `## ${cat} (${catEntries.length})`;
    if (totalChars + header.length + 1 > MEMORY_INJECTION_MAX_CHARS) {
      truncated = true;
      break;
    }
    lines.push(header);
    totalChars += header.length + 1;

    for (const entry of catEntries) {
      const title = entry.title ? String(entry.title) : entry.id;
      const compact = entry.content.replace(/\s+/g, ' ').trim();
      const summary = compact.length > 280 ? `${compact.slice(0, 277)}...` : compact;
      const line = `- [${title}] ${summary}`;

      if (totalChars + line.length + 1 > MEMORY_INJECTION_MAX_CHARS) {
        truncated = true;
        break;
      }
      lines.push(line);
      totalChars += line.length + 1;
    }

    if (truncated) break;
    lines.push('');
    totalChars += 1;
  }

  if (lines.length === 0) {
    return '';
  }

  if (truncated) {
    lines.push(
      `...(truncated — ${totalEntries} total entries; showing prefix up to ~${MEMORY_INJECTION_MAX_CHARS} chars)`,
    );
  }

  return lines.join('\n').trimEnd();
}

